<?php
namespace App\Domains\Evidence\Models;
use App\Domains\Inventory\Models\InventoryObjectUnit; use App\Domains\Reference\Models\Supplier; use Illuminate\Database\Eloquent\Model;
class SupplierProductObservation extends Model { protected $fillable=['evidence_record_id','supplier_id','inventory_object_unit_id','purchase_price','currency_code','minimum_order_quantity','available_quantity','product_specification','freight_amount','freight_terms','payment_terms','lead_time_days','discount_amount','discount_description','supplier_location']; protected $casts=['purchase_price'=>'decimal:6','minimum_order_quantity'=>'decimal:6','available_quantity'=>'decimal:6','freight_amount'=>'decimal:6','discount_amount'=>'decimal:6']; public function evidence(){return $this->belongsTo(EvidenceRecord::class,'evidence_record_id');} public function supplier(){return $this->belongsTo(Supplier::class);} public function inventoryObjectUnit(){return $this->belongsTo(InventoryObjectUnit::class);} }
